// Helper function to find ability by name (case-insensitive, partial match)
export function findAbility(name: string): WikiAbility | undefined {
  const normalizedName = name.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, '_');
  
  // Try exact match first
  if (WIKI_ABILITIES[normalizedName]) {
    return WIKI_ABILITIES[normalizedName];
  }
  
  // Try partial match
  for (const [key, ability] of Object.entries(WIKI_ABILITIES)) {
    if (key.includes(normalizedName) || normalizedName.includes(key)) {
      return ability;
    }
    if (ability.name.toLowerCase().includes(name.toLowerCase())) {
      return ability;
    }
  }
  
  return undefined;
}
